package com.interviewcoach.api;
import com.interviewcoach.config.SecurityConfig;import com.interviewcoach.model.*;import com.interviewcoach.repo.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.time.temporal.ChronoUnit;import java.security.SecureRandom;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final UserRepo users;private final AuthTokenRepo tokens;private final PasswordEncoder encoder;public AuthController(UserRepo u,AuthTokenRepo t,PasswordEncoder e){users=u;tokens=t;encoder=e;}
 public record Register(@NotBlank String name,@Email @NotBlank String email,@Size(min=8,max=100) String password){} public record Login(@Email String email,String password){}
 @PostMapping("/register") @Transactional public Map<String,Object> register(@Valid @RequestBody Register r){if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");User u=new User();u.name=r.name().trim();u.email=r.email().toLowerCase(Locale.ROOT).trim();u.passwordHash=encoder.encode(r.password());users.save(u);return issue(u);}
 @PostMapping("/login") @Transactional public Map<String,Object> login(@RequestBody Login r){User u=users.findByEmailIgnoreCase(r.email()==null?"":r.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!encoder.matches(r.password()==null?"":r.password(),u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return issue(u);}
 private Map<String,Object> issue(User u){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);AuthToken t=new AuthToken();t.user=u;t.tokenHash=SecurityConfig.hash(raw);t.expiresAt=Instant.now().plus(12,ChronoUnit.HOURS);tokens.save(t);return Map.of("token",raw,"name",u.name,"email",u.email,"expiresAt",t.expiresAt.toString());}
 @PostMapping("/logout")@Transactional public void logout(@RequestHeader("Authorization")String auth){if(auth.startsWith("Bearer "))tokens.deleteByTokenHash(SecurityConfig.hash(auth.substring(7)));}
}
